mapper.select:
SELECT COUNT(1)
FROM song_likes
WHERE user_id = #{userId}
  AND song_id = #{songId}

mapper.delete:
DELETE FROM song_likes
WHERE user_id = #{userId}
  AND song_id = #{songId}

mapper.update:
UPDATE songs
SET like_count = like_count + 1
WHERE id = #{songId}

UPDATE songs
SET like_count = GREATEST(like_count - 1, 0)
WHERE id = #{songId}

mapper.select:
SELECT COALESCE(like_count, 0)
FROM songs
WHERE id = #{songId}
